(7525431, 1202865, 179769, '<td valign="top">I''m giving a 6 for cuteness!!</td>', 'I''m giving a 6 for cuteness!!', '2017-07-25 19:13:52.000000', NULL, 1),
(7525442, 1202839, 30049, '<td valign="top">Not quite as sharp as it should be for the subject material, but given it''s a true "Tight Crop" (compared to many that are not) I''m nudging my vote up a smidge.  Good luck.</td>', 'Not quite as sharp as it should be for the subject material, but given it''s a true "Tight Crop" (compared to many that are not) I''m nudging my vote up a smidge.  Good luck.', '2017-07-25 21:19:49.000000', NULL, 1),
