(7525598, 1202767, 173844, '<td valign="top">Vibrantly up close.  Don''t mess with Mom.</td>', 'Vibrantly up close.  Don''t mess with Mom.', '2017-07-26 10:01:42.000000', NULL, 1),
(7525599, 1202874, 173844, '<td valign="top">Extravagantly close and detailed, packs a lot of personality in there.  Led me to contemplate the whole, disassemble the features and then put them together again.  Very nice.</td>', 'Extravagantly close and detailed, packs a lot of personality in there.  Led me to contemplate the whole, disassemble the features and then put them together again.  Very nice.', '2017-07-26 10:07:09.000000', NULL, 1),
(7525600, 1202849, 173844, '<td valign="top">For them I''d say it''s after.  Packs a chilling punch.</td>', 'For them I''d say it''s after.  Packs a chilling punch.', '2017-07-26 10:08:55.000000', NULL, 1),
(7525601, 1202887, 173844, '<td valign="top">I''m happy with this depth of field, allowed to leisurely examine the amazing composite eyes.  And that tiger-striped body!  Adroit composition.</td>', 'I''m happy with this depth of field, allowed to leisurely examine the amazing composite eyes.  And that tiger-striped body!  Adroit composition.', '2017-07-26 10:13:15.000000', NULL, 1),
(7525602, 1202672, 173844, '<td valign="top">Lovely whimsy.  Piques the imagination.  Very enjoyable.</td>', 'Lovely whimsy.  Piques the imagination.  Very enjoyable.', '2017-07-26 10:16:31.000000', NULL, 1),
(7525603, 1202868, 173844, '<td valign="top">Terrific portrait, offers a hefty dollop of personality.  The earring on the right is visually distracting, in my opinion.</td>', 'Terrific portrait, offers a hefty dollop of personality.  The earring on the right is visually distracting, in my opinion.', '2017-07-26 10:19:16.000000', NULL, 1),
(7525604, 1202697, 173844, '<td valign="top">Great close-up.  If I don''t pull back I find my vision shuttling between this toad''s eyes, which is dizzying.  His expression challenges Mona Lisa''s, in an amphibious sort of way.  Bland disdain, stoic amusement, mystical detachment ---  he''s not saying.</td>', 'Great close-up.  If I don''t pull back I find my vision shuttling between this toad''s eyes, which is dizzying.  His expression challenges Mona Lisa''s, in an amphibious sort of way.  Bland disdain, stoic amusement, mystical detachment ---  he''s not saying.', '2017-07-26 10:26:20.000000', NULL, 1),
(7525605, 1202409, 173844, '<td valign="top">Not sure why, but there''s a feeling of profundity here.  I quite like it, and will leave it at that.</td>', 'Not sure why, but there''s a feeling of profundity here.  I quite like it, and will leave it at that.', '2017-07-26 10:28:05.000000', NULL, 1),
(7525633, 1202866, 12611, '<td valign="top">Beautifully soft, and great color.</td>', 'Beautifully soft, and great color.', '2017-07-26 13:08:06.000000', NULL, 1),
