(7525668, 1202763, 173844, '<td valign="top">So cute of its kind.  Warm, glossy eyes, not opaque but of limitless depth.  Mentally I''m reaching for a napkin.</td>', 'So cute of its kind.  Warm, glossy eyes, not opaque but of limitless depth.  Mentally I''m reaching for a napkin.', '2017-07-26 14:01:16.000000', NULL, 1),
(7525669, 1202441, 173844, '<td valign="top">A vast scene that certainly fills the frame, with a frill of sky.  And that sky drips down the image like generous icing on a cake.  Intricate and absorbing.</td>', 'A vast scene that certainly fills the frame, with a frill of sky.  And that sky drips down the image like generous icing on a cake.  Intricate and absorbing.', '2017-07-26 14:04:26.000000', NULL, 1),
