(7525870, 1202874, 30049, '<td valign="top">I need a new "thumbs up icon".  In the meantime - Congrats!  Well done.</td>', 'I need a new "thumbs up icon".  In the meantime - Congrats!  Well done.', '2017-07-28 07:18:28.000000', NULL, 0),
(7525871, 1202874, 6519, '<td valign="top">I lost all of the LONG comment I made on this, but just for you, I''ll re-type at least a bit of it:<br/> <br/>Ken, I was fairly sure I recognized Riley, but I was not swayed by my secret online-Ken-adoration.<br/>I loved that your submission was totally on-challenge...... something that is important to me on THIS website/forum.  <br/> <br/>The colours, details, sharpness, etc totally deserve the ribbon you earned.<br/> <br/>Give an extra hug to Riley and tell him, that I, too, know he will learn to appreciate his Dad''s photographic passion in years to come. <br/>He''ll roll his eyes for now, I bet, but give him another 30 years or so, and he''ll "get us".</td>', 'I lost all of the LONG comment I made on this, but just for you, I''ll re-type at least a bit of it: Ken, I was fairly sure I recognized Riley, but I was not swayed by my secret online-Ken-adoration.I loved that your submission was totally on-challenge...... something that is important to me on THIS website/forum.   The colours, details, sharpness, etc totally deserve the ribbon you earned. Give an extra hug to Riley and tell him, that I, too, know he will learn to appreciate his Dad''s photographic passion in years to come. He''ll roll his eyes for now, I bet, but give him another 30 years or so, and he''ll "get us".', '2017-07-28 07:36:25.000000', NULL, 0),
(7525873, 1202874, 3306, '<td valign="top">Congrats on the ribbon. It is well deserved.</td>', 'Congrats on the ribbon. It is well deserved.', '2017-07-28 08:00:51.000000', NULL, 0),
(7525875, 1202874, 60581, '<td valign="top">Time flies! He is 5 years back and now :)<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1034560" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/1000-1999/1636/120/Copyrighted_Image_Reuse_Prohibited_1034560.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/1000-1999/1636/120/Copyrighted_Image_Reuse_Prohibited_1034560.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/1000-1999/1636/120/Copyrighted_Image_Reuse_Prohibited_1034560.jpg"/></a></td>', 'Time flies! He is 5 years back and now :) ', '2017-07-28 08:39:12.000000', NULL, 0),
